 @AfterEach void close(){scope.close();TransactionSynchronizationManager.clear();}
 List<?> query(String sql,RowMapper<?> mapper,Object[] args)throws Exception{
  reads.add(sql);var m=java.util.regex.Pattern.compile("SELECT (.+?) FROM (\\w+)(?: WHERE (.*?))?(?: ORDER BY (\\w+))?(?: LIMIT (\\d+))?$").matcher(sql);assertTrue(m.matches(),sql);String fields=m.group(1),table=m.group(2),where=m.group(3);List<Map<String,Object>> result=new ArrayList<>();
  for(var row:tables.getOrDefault(table,List.of())){int n=0;boolean ok=true;if(where!=null)for(String term:where.split(" AND ")){if(term.endsWith(" IS NULL")){ok&=row.get(term.substring(0,term.length()-8))==null;continue;}String[] kv=term.split("=",2);assertEquals(2,kv.length,sql);String rhs=kv[1];Object expected=rhs.equals("?")?args[n++]:rhs.startsWith("'")?rhs.substring(1,rhs.length()-1):rhs.matches("[0-9]+")?rhs:row.get(rhs);ok&=Objects.equals(normal(row.get(kv[0])),normal(expected));}if(ok)result.add(row);}
  if(m.group(4)!=null)result.sort(Comparator.comparing(r->r.get(m.group(4)).toString()));if(fields.equals("COUNT(*)"))return map(mapper,List.of(Map.of("count",result.size())));if(m.group(5)!=null&&result.size()>Integer.parseInt(m.group(5)))result=result.subList(0,Integer.parseInt(m.group(5)));
  if(!fields.equals("*")){List<Map<String,Object>> projected=new ArrayList<>();for(var row:result){var p=new LinkedHashMap<String,Object>();for(String field:fields.split(",")){assertTrue(row.containsKey(field),"Unknown SQL column "+table+"."+field);p.put(field,row.get(field));}projected.add(p);}result=projected;}return map(mapper,result);
 }
 Object normal(Object v){return v==null?null:v.toString();}
 List<?> map(RowMapper<?> mapper,List<Map<String,Object>> rows)throws Exception{var result=new ArrayList<>();for(var row:rows){var rs=mock(ResultSet.class);org.mockito.stubbing.Answer<Object> value=i->{Object key=i.getArgument(0);return row.get(key instanceof Integer?new ArrayList<>(row.keySet()).get((Integer)key-1):key);};when(rs.getString(anyString())).thenAnswer(i->{var v=value.answer(i);return v==null?null:v.toString();});when(rs.getString(anyInt())).thenAnswer(i->{var v=value.answer(i);return v==null?null:v.toString();});when(rs.getInt(anyInt())).thenAnswer(i->Integer.parseInt(value.answer(i).toString()));when(rs.getTimestamp(anyString())).thenAnswer(i->Timestamp.valueOf((LocalDateTime)value.answer(i)));when(rs.getTimestamp(anyInt())).thenAnswer(i->Timestamp.valueOf((LocalDateTime)value.answer(i)));result.add(mapper.mapRow(rs,result.size()));}return result;}
 FormalVerificationJobs.Job create()throws Exception{return jobs.create(admission,prepared);}
 @Test void actualCreateRegistersAndIndependentlyRereadsEveryLedgerWithDates()throws Exception{var job=create();assertEquals(now,job.created());assertEquals(job,jobs.read(tenant,id(5)).orElseThrow());assertTrue(job.dependencies().contains("2026-10-17"));assertEquals(3,tables.get("formal_model_manifest").size());assertEquals(5,tables.get("version_registry").size());assertEquals("READY",tables.get("run_step").get(0).get("status"));assertEquals(0,tables.get("run_step").get(0).get("lease_generation"));assertTrue(writes.stream().noneMatch(s->s.contains("model_invocation")||s.contains("formal_invocation_attempt")||s.contains("budget_reservation")));verify(prepared,times(2)).requireCurrent(admission);String output=System.getProperty("formal.create.captureDirectory");if(output!=null){Path folder=Path.of(output);Files.createDirectories(folder);Files.write(folder.resolve("actual-insert-sql.txt"),writes);Files.write(folder.resolve("actual-select-sql.txt"),reads);Files.writeString(folder.resolve("actual-rows.json"),schema.canonical(AgentPublicationWitness.tree(tables)));}}
